prototypeCSS:
main[data-reading-concept] {--concept-actions:calc(var(--control-min-size) + 2 * var(--border-width) + var(--space-3));}
main[data-reading-concept]>.picker-content {grid-template-rows:minmax(0,1fr) calc(2 * var(--type-body-line) + 2 * var(--space-2) + var(--space-3) + var(--border-width)) var(--concept-actions);}
[data-reading-concept] .results-area {padding-bottom:var(--space-2);scroll-padding-bottom:var(--space-2);box-sizing:border-box;}
[data-reading-concept] .format-preview {grid-row:2;grid-column:1;height:auto;box-sizing:border-box;margin:var(--space-3) var(--space-3) 0;padding:var(--space-2) var(--space-3);overflow:hidden!important;border:var(--border-width) solid var(--line);border-bottom:0;border-radius:var(--result-radius) var(--result-radius) 0 0;background:var(--hover-background);}
[data-reading-concept] .format-preview .preview-text {height:calc(2 * var(--type-body-line));overflow:hidden;}
[data-reading-concept] .prototype-composer-bar {grid-row:3;grid-column:1;display:grid;grid-template-columns:minmax(0,1fr) auto auto;column-gap:var(--space-1);margin:0 var(--space-3) var(--space-3);padding:0 var(--space-1);border:var(--border-width) solid var(--line);border-top-color:transparent;border-radius:0 0 var(--result-radius) var(--result-radius);background:var(--hover-background);}
