[data-reading-concept] .prototype-composer-bar button:first-child {justify-self:start;text-align:start;}
[data-reading-concept] .prototype-composer-bar .concept-copy {min-width:0;background:var(--button-background);color:var(--text);font-weight:400;}
[data-reading-concept] .prototype-composer-bar .concept-copy:disabled {opacity:.5;}
[data-reading-concept] .concept-reader-heading {display:none;}
main[data-reading-concept][data-concept-compact]>.picker-content {grid-template-rows:minmax(0,1fr) 0 calc(var(--concept-actions) + var(--space-2));}
