main[data-reading-concept][data-concept-view]>.picker-content {grid-template-rows:calc(var(--control-min-size) + 2 * var(--space-1)) minmax(0,1fr) var(--concept-actions);}
[data-reading-concept][data-concept-view] .results-area {display:none!important;}
