[data-reading-concept][data-concept-view="selection"] [aria-label="Selected references"] {display:flex!important;grid-row:2;grid-column:1;position:static;inset:auto;margin:0 var(--space-3);padding:var(--space-3);overflow:auto!important;min-height:0!important;max-height:none!important;align-content:flex-start;background:var(--surface);border:0;}
